<script setup>
import {ref,computed} from 'vue';
import {state,notify} from '../state';
import {storage} from '../storage';
import {t,number} from '../i18n';
import {localDate} from '../../core/calendar.mjs';
import {projectReportPdf} from '../project-report.mjs';
import {calibrationPdf,physicalPatternPdf,printCorrection} from '../physical-print.mjs';
import InventoryLabels from './InventoryLabels.vue';
import EntityForm from './EntityForm.vue';
const props=defineProps({project:Object});const form=ref(null),labeling=ref(false);
const revision=computed(()=>state.value.patterns.find(row=>row.id===props.project.patternId)?.revisions.find(row=>row.id===props.project.revisionId));
const languageFields=()=>[{key:'locale',label:t('language'),type:'select',required:true,options:[{value:'it',label:'Italiano'},{value:'en',label:'English'}]},{key:'paper',label:t('paper'),type:'select',required:true,options:['a4','letter']}];
const initial=()=>({locale:state.value.settings.language,paper:state.value.settings.paper});
function report(){form.value={title:t('projectReport'),fields:[...languageFields(),{key:'includeRecipient',label:t('reportIncludeRecipient'),type:'checkbox',wide:true},{key:'includePrivateNotes',label:t('reportIncludeNotes'),type:'checkbox',wide:true}],initial:{...initial(),includeRecipient:false,includePrivateNotes:false},help:t('reportPrivacyHelp'),submit:async draft=>{const data=await projectReportPdf(state.value,props.project.id,{...draft,asOf:localDate()});return storage.saveFile({name:`${props.project.name}-report-${draft.locale}.pdf`,data});}};}
function calibration(){form.value={title:t('printCalibration'),fields:languageFields(),initial:initial(),help:t('printCalibrationHelp'),submit:async draft=>{return storage.saveFile({name:'Ricamo-calibration.pdf',data:await calibrationPdf(draft)});}};}
function actualSize(){form.value={title:t('physicalPattern'),fields:[...languageFields(),{key:'countX',label:t('physicalCountX'),type:'number',required:true},{key:'countY',label:t('physicalCountY'),type:'number',required:true},{key:'countMeaning',label:t('physicalCountMeaning'),type:'select',required:true,options:[{value:'stitches',label:()=>t('physicalCountStitches')},{value:'threads',label:()=>t('physicalCountThreads')}]},{key:'overX',label:t('physicalOverX'),type:'number',required:true,when:d=>d.countMeaning==='threads'},{key:'overY',label:t('physicalOverY'),type:'number',required:true,when:d=>d.countMeaning==='threads'}],initial:{...initial(),countX:'',countY:'',countMeaning:'stitches',overX:2,overY:2},help:t('physicalPatternHelp'),submit:async draft=>{return storage.saveFile({name:`${props.project.name}-actual-size.pdf`,data:await physicalPatternPdf(revision.value,{...draft,title:props.project.name,thread:props.project.settings.thread??{}})});}};}
const measured=ref(''),correction=computed(()=>{try{return measured.value?printCorrection(measured.value):null;}catch{return null;}});
</script>
<template><section class="panel"><div class="panel-heading"><h2>{{t('projectDocuments')}}</h2></div><div class="panel-body"><div class="toolbar"><button class="button" @click="labeling=true">{{t('projectLabel')}}</button><button class="button" @click="report">{{t('projectReport')}}</button><button class="button" @click="calibration">{{t('printCalibration')}}</button><button v-if="revision" class="button" @click="actualSize">{{t('physicalPattern')}}</button></div><p class="field-help">{{t('reportPrivacyHelp')}}</p><details><summary>{{t('printCorrection')}}</summary><label :for="`measured-${project.id}`">{{t('measuredRuler')}}</label><input :id="`measured-${project.id}`" v-model="measured" inputmode="decimal"/><p class="field-help">{{t('printCorrectionHelp')}}</p><p v-if="correction!==null" role="status">{{t('suggestedPrintScale')}}: {{number(correction,3)}}%</p></details></div></section><EntityForm v-if="form" :title="form.title" :fields="form.fields" :initial="form.initial" :submit="form.submit" :help="form.help" :confirm-label="t('exportPdf')" @close="form=null" @saved="form=null;notify()"/><InventoryLabels v-if="labeling" :project-ids="[project.id]" @close="labeling=false"/></template>
